<script setup lang="ts">
import { families, bps } from '#shared/admin'
import { errorMessages, cents, dateLabel } from '~/utils/format'
useHead({title:'Catálogo · JARVIS'})
type Item = {id:string;sku:string;description:string;family:keyof typeof families;unit:string;active:boolean;versions:{id:string;version:number;price_cents:string;cost_cents:string;tax_bps:number;valid_until:string;status:string}[]}
const {data,error,refresh}=await useFetch<{data:Item[]}>('/api/backend/admin/catalog')
const errors=ref<string[]>([]),success=ref(''),pending=ref(false),selected=ref('')
const item=reactive({sku:'',description:'',family:'',unit:''}), price=reactive({price:'',cost:'',tax:'',valid_until:'',reason:''})
const current=computed(()=>data.value?.data.find(i=>i.id===selected.value))
async function create(){if(pending.value)return;pending.value=true;errors.value=[];success.value='';try{const r=await $fetch<{data:{id:string}}>('/api/backend/admin/catalog',{method:'POST',body:item});selected.value=r.data.id;Object.assign(item,{sku:'',description:'',family:'',unit:''});success.value='Ítem creado. Publica su primer precio en el formulario de precios.';await refresh()}catch(e){errors.value=errorMessages(e)}finally{pending.value=false}}
async function publish(){if(pending.value)return;pending.value=true;errors.value=[];success.value='';try{const tax=bps(price.tax);if(!Number.isInteger(tax)||tax>10000)throw {data:{message:'Ingresa un impuesto entre 0 y 100 %, con hasta dos decimales.'}};await $fetch(`/api/backend/admin/catalog/${selected.value}/prices`,{method:'POST',body:{price:price.price.replace(',','.'),cost:price.cost.replace(',','.'),tax_bps:tax,valid_until:price.valid_until,reason:price.reason}});Object.assign(price,{price:'',cost:'',tax:'',valid_until:'',reason:''});success.value='Nueva versión de precio publicada.';await refresh()}catch(e){errors.value=errorMessages(e)}finally{pending.value=false}}
async function toggle(){if(pending.value||!current.value)return;pending.value=true;errors.value=[];success.value='';try{await $fetch(`/api/backend/admin/catalog/${selected.value}/active`,{method:'PATCH',body:{active:!current.value.active}});success.value='Estado del ítem actualizado.';await refresh()}catch(e){errors.value=errorMessages(e)}finally{pending.value=false}}
watch(selected,()=>Object.assign(price,{price:'',cost:'',tax:'',valid_until:'',reason:''}))
</script>
<template><AdminShell title="Catálogo y precios" description="Crea ítems y publica versiones de precio conservando su historial." :errors="errors" :success="success"><div v-if="error" class="admin-error" role="alert">No pudimos cargar el catálogo. <button class="button secondary" @click="refresh()">Reintentar</button></div><div class="admin-grid"><section class="admin-card"><h2>1. Crear ítem</h2><form class="admin-form" @submit.prevent="create"><label>SKU<input v-model="item.sku" required maxlength="60" pattern="[A-Za-z0-9_-]+"></label><label>Descripción<input v-model="item.description" required maxlength="255"></label><label>Familia<select v-model="item.family" required><option value="">Seleccionar…</option><option v-for="(label,key) in families" :key="key" :value="key">{{ label }}</option></select></label><label>Unidad<select v-model="item.unit" required><option value="">Seleccionar…</option><option v-for="unit in ['unidad','metro','hora','servicio','licencia']" :key="unit">{{ unit }}</option></select></label><button class="button primary" :disabled="pending">Crear ítem</button></form></section><section class="admin-card"><h2>2. Publicar precio</h2><form class="admin-form" @submit.prevent="publish"><label>Ítem del catálogo<select v-model="selected" required><option value="">Seleccionar…</option><option v-for="i in data?.data" :key="i.id" :value="i.id">{{ i.sku }} · {{ i.description }}</option></select></label><p v-if="!data?.data.length && !error" class="admin-muted">Crea el primer ítem para asignar su precio.</p><template v-if="current"><label>Precio de venta (COP)<input v-model="price.price" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required></label><label>Costo (COP)<input v-model="price.cost" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required></label><label>Impuesto (%)<input v-model="price.tax" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required></label><label>Vigente hasta<input v-model="price.valid_until" type="date" required></label><label>Motivo del cambio<textarea v-model="price.reason" required minlength="5" maxlength="1000" /></label><p class="admin-muted">La versión anterior quedará como histórica. Los montos se ingresan sin separadores de miles.</p><button class="button primary" :disabled="pending">Publicar nueva versión</button></template></form></section></div><section v-if="current" class="admin-card admin-section"><div class="admin-actions"><h2>{{ current.sku }} · Historial de precios</h2><span>{{ current.active ? 'Activo' : 'Inactivo' }}</span><button class="button secondary" :disabled="pending" @click="toggle">{{ current.active?'Desactivar ítem':'Activar ítem' }}</button></div><p class="admin-muted">{{ families[current.family] }} · {{ current.unit }}. Las versiones anteriores se conservan y no se editan.</p><p v-if="!current.versions.length" class="admin-muted">Este ítem todavía no tiene precios.</p><div v-else class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Versión</th><th>Venta</th><th>Costo</th><th>Impuesto</th><th>Vigente hasta</th><th>Estado</th></tr></thead><tbody><tr v-for="v in current.versions" :key="v.id"><td>{{ v.version }}</td><td>{{ cents(v.price_cents) }}</td><td>{{ cents(v.cost_cents) }}</td><td>{{ v.tax_bps/100 }} %</td><td>{{ dateLabel(v.valid_until) }}</td><td>{{ v.status==='approved'?'Aprobado':v.status==='historical'?'Histórico':v.status }}</td></tr></tbody></table></div></section></AdminShell></template>
